// Replays the recorded actual history only; no hypothetical search or recommendations.
module.exports = function(log) {
 const cols="ABCDEFGHJ", b={}, captures={X:0,O:0}, moves=[], checks=[]; let ko=null;
 for(let y=1;y<=9;y++)for(const c of cols)b[c+y]=".";
 const nb=p=>{const x=cols.indexOf(p[0]),y=+p[1];return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,c])=>a>=0&&a<9&&c>=1&&c<=9).map(([a,c])=>cols[a]+c);};
 const group=p=>{let seen=new Set([p]),q=[p],lib=new Set();while(q.length){let u=q.pop();for(let v of nb(u)){if(b[v]===".")lib.add(v);else if(b[v]===b[p]&&!seen.has(v)){seen.add(v);q.push(v);}}}return {stones:[...seen],liberties:[...lib]};};
 function play(color,p){const enemy=color==="X"?"O":"X", removed=[];if(p==="pass"){ko=null;return removed;}if(b[p]!==".")throw Error("Occupied "+p);if(p===ko)throw Error("Ko "+p);b[p]=color;for(let v of nb(p))if(b[v]===enemy){let g=group(v);if(!g.liberties.length){for(let u of g.stones){b[u]=".";removed.push(u);}}}let own=group(p);if(!own.liberties.length)throw Error("Suicide "+p);captures[color]+=removed.length;ko=removed.length===1&&own.stones.length===1&&own.liberties.length===1?removed[0]:null;return removed;}
 function check(e){const s=e.response.content.filter(x=>x.type==="text").map(x=>x.text).join("\n");let n=0;for(let l of s.split("\n")){let m=l.match(/^\s*([1-9])\s+([XO.](?:\s+[XO.]){8})\s+[1-9]\s*$/);if(m)m[2].split(/\s+/).forEach((v,i)=>{let p=cols[i]+m[1];if(b[p]!==v)throw Error("Board mismatch "+p);n++;});}if(n!==81)throw Error("Incomplete board");let c=s.match(/Captured by Black: (\d+); by White: (\d+)/);if(!c||+c[1]!==captures.X||+c[2]!==captures.O)throw Error("Capture mismatch");let k=s.match(/Ko point: ([A-HJ][1-9]|none)/);if(!k||(k[1]==="none"?null:k[1])!==ko)throw Error("Ko mismatch");let mn=s.match(/Move number: (\d+)/);if(!mn||+mn[1]!==moves.length+1)throw Error("Move number mismatch");checks.push({type:e.type,moves:moves.length,captures:{...captures},ko,boardPoints:n});}
 let mi=0;
 for(let e of log.events){if(e.type==="choose_opponent"){let v=log.moves[mi++];let removed=play("X",v.move);moves.push({...v,removed});}else if(e.type==="play"){for(let i=0;i<2;i++){let v=log.moves[mi++];let removed=play(v.color==="B"?"X":"O",v.move);moves.push({...v,removed});}}check(e);}
 if(mi!==log.moves.length)throw Error("Move count mismatch");
 return {moves,checks,finalCaptures:captures,finalStones:{Black:Object.values(b).filter(v=>v==="X").length,White:Object.values(b).filter(v=>v==="O").length},board:b};
};
